Assert-True ($world -match 'rig.ExternalGroup <= 4' -and $world -match 'JointDiagnosticSamples = 3' -and $world -match 'maxAnchorGapMm' -and $world -match 'admissionDeltaDeg') "head joint and anchor separation diagnostics are bounded to four rigs and three samples"
Assert-True ($nativeBridge -match 'rptpx_unity_get_scene_settings' -and $nativeBridge -match 'settings->solver_type\s*=\s*static_cast<uint32_t>\(PxSolverType::ePGS\)' -and $nativeBridge -match 'getFrictionType\(\)' -and $nativeBridge -match 'getFlags\(\)' -and $meshSources -match 'SourceSceneSettings' -and $runtime -match 'source parity') "the external scene waits for the version-gated Unity source solver plus live friction and contact-solver flags"
Assert-True ($nativeBridge -match 'scene_desc\.solverType\s*=\s*static_cast<PxSolverType::Enum>\(desc->solver_type\)' -and $nativeBridge -match 'scene_desc\.frictionType\s*=\s*static_cast<PxFrictionType::Enum>\(desc->friction_type\)' -and $nativeBridge -match 'copy_source_scene_flags\(scene_desc\.flags,\s*desc->scene_flags\)' -and $nativeBridge -notmatch 'solverType\s*=\s*PxSolverType::eTGS') "external PhysX applies source scene solver, friction, and relevant flags instead of forcing TGS"
Assert-True ($nativeBridge -match 'eENABLE_CCD' -and $nativeBridge -match 'eDETECT_CCD_CONTACT') "CCD symbols are wired; executable thin-wall and handoff regressions run in the native suite"
Assert-True ($nativeScene -match 'SolverPositionIterations\s*=\s*\(uint\)body\.solverIterations' -and $nativeScene -match 'SolverVelocityIterations\s*=\s*\(uint\)body\.solverVelocityIterations' -and $nativeScene -notmatch 'Math\.Max\((8|2),\s*body\.solver') "external bodies preserve each Unity Rigidbody solver iteration count exactly"
Assert-True ($nativeBridge -match 'was_kinematic\s*!=\s*will_be_kinematic' -and $nativeBridge -match 'clearForce\(PxForceMode::eFORCE\)' -and $nativeBridge -match 'clearForce\(PxForceMode::eIMPULSE\)' -and $nativeBridge -match 'clearTorque\(PxForceMode::eIMPULSE\)') "dynamic and kinematic ownership transitions defensively discard interrupted force and impulse accumulators"
Assert-True ($world -match 'foreach \(Collider corpseCollider in corpseBody\.NativeColliders\)' -and $world -match '_externalRuntime\.IgnoreCollision\(effectCollider,\s*corpseCollider\)' -and $world -match 'native\.position\s*=\s*simulation\.position' -and $world -match 'native\.rotation\s*=\s*simulation\.rotation' -and $killPatch -notmatch 'colliderForce') "external gore is presented and excluded from its source corpse while the retired arterial-particle collider-force hook stays absent"
Assert-True ($contracts -match 'EnvironmentOnly\s*=\s*1' -and $world -match 'RegisterLocalDetachedGib' -and $world -match 'NetworkPoseEligible\s*=\s*!localEnvironmentOnly' -and $world -match 'ConfigureLocalGibQueryCollider' -and $world -match 'excludeLayers\s*=\s*new LayerMask \{ value = ~0 \}' -and $nativeScene -match 'collisionProfile\s*==\s*ExternalCollisionProfile\.DeadbodyAndEnvironment') "procedural limb gibs keep query-only Unity meshes, environment-only external contacts, and no Fika motion snapshots"
Assert-True ($contracts -match 'ExternalTransientConvexShape' -and $contracts -match 'IExternalBodyCreation' -and $contracts -match 'WorkerMilliseconds' -and $contracts -match 'BeginCreateTransientConvexBody' -and $runtime -match 'DelegateWork work = new DelegateWork' -and $runtime -match 'Work\.IsCompleted' -and $runtime -notmatch 'BeginCreateTransientConvexBody[\s\S]{0,2600}Task\.Wait') "transient convex bodies are created, timed, and polled without synchronously waiting on the owner thread"
Assert-True ($limbs -match 'PendingExternalShapes' -and $limbs -match 'generatedShapes\.Add\(new ExternalTransientConvexShape' -and $world -match 'transientShapes == null \|\| transientShapes\.Length == 0' -and $world -notmatch 'TryCaptureTransientConvexShapes') "validated gib proxy arrays pass directly into external PhysX without Unity mesh re-extraction"
Assert-True ($nativeScene -match 'TransientMesh' -and $nativeScene -match 'rptpx_create_transient_mesh_from_cooked' -and $nativeScene -match '_transientMeshesByActor' -and $nativeScene -notmatch 'if \(transient\)[\s\S]{0,700}File\.WriteAllBytes' -and $nativeApi -match 'rptpx_destroy_mesh' -and $nativeHeader -match 'rptpx_destroy_mesh') "transient gib meshes bypass persistent cache files and release native mesh handles with their actor"
Assert-True ($runtime -match 'NotifySceneLoaded' -and $runtime -match 'late-scene' -and $runtime -match 'runtime-proximity' -and $runtime -match 'AuditStaticActors' -and $runtime -match 'TryPromoteStaticActor' -and $runtime -match 'CaptureEnvironment\(actor\.Root,\s*colliders,\s*movable:\s*true' -and $nativeScene -match 'ReplaceNative') "late scenes, runtime-spawn safety discovery, and moved-static to kinematic promotion are present"
Assert-True ($runtime -match 'EnvironmentShapeAuditPerFrame\s*=\s*64' -and $runtime -match 'StaticAuditPerFrame\s*=\s*16' -and $runtime -match '_movableEnvironmentActors' -and $runtime -match 'AuditEnvironmentShapes\(\)' -and $runtime -notmatch 'RuntimeCensusIntervalFrames' -and $runtime -notmatch '_nextRuntimeCensusFrame') "steady-state environment maintenance audits bounded slices and directly visits only registered movable actors"
Assert-True ($runtime -notmatch 'name\.IndexOf\("Interactive"' -and $runtime -match 'name\.IndexOf\("Door"' -and $runtime -match 'generic[\s\r\n]+// Interactive components') "generic interactive ancestors cannot classify fixed map geometry as per-frame movable while known doors remain explicit"
Assert-True ($runtime -match 'runtime-proximity' -and $world -match 'FullPrebakeRuntimeProbeIntervalFrames\s*=\s*60' -and $world -match 'NextEnvironmentRefreshFrame') "full prebake discovers runtime-spawned colliders through staggered local safety probes"
Assert-True ($world -match 'CenterBody' -and $world -match 'centerBody\.Proxy\.TransformPoint' -and $world -match 'MaximumProximityAcquiresPerFrame\s*=\s*2' -and $world -match '_environmentRefreshCursor' -and $runtime -match '_proximityUnknownScratch') "active Update uses a representative cached pose, fair bounded proximity work, and reusable query collections"
Assert-True ($world -match 'DetachWeaponFromCorpse' -and $world -notmatch 'ProxyWeaponJoint|SyncWeaponJointState|TryCopyWeaponJoint' -and $world -match 'CountAwakeIndependentBodies' -and $weaponState -notmatch 'isKinematic\s*=\s*true') "weapons remain independent naturally sleeping dynamic bodies after the corpse-hand joint is destroyed"
Assert-True ($contracts -match 'ExternalRoundedBoxShape' -and $contracts -match 'TryCreateRoundedBoxBody' -and $runtime -match 'ActorSnapshot\.CaptureRoundedBoxBody' -and $mesh -match 'CreateWeaponRoundedBox' -and $mesh -match 'WeaponRoundedBoxArcSegments\s*=\s*4' -and $mesh -match 'full-thickness-ridge' -and $mesh -notmatch 'ReadWeaponConvex|BakeMesh' -and $world -notmatch 'TryBuildWeaponConvex' -and $world -match 'procedural rounded-box cooking failed; using the fitted box fallback') "weapon shadows retain broad side faces while narrow supports meet at a fully rounded central ridge without attachment mesh readback"
Assert-True ($world -match 'WeaponColliderGeometry.TryFitOriented' -and $contracts -match 'ActorSpace' -and $nativeScene -match 'roundedBox.Rotation' -and $nativeScene -match 'box.Rotation' -and $world -notmatch 'CollectWeaponRendererBounds|EncapsulateWorldBounds') "weapon fitting carries its authored collider frame into both rounded and fallback shapes independently of render state and world AABBs"
Assert-True ($shotImpact -match 'independentWeaponHit[\s\S]{0,400}PrepareCorpseImpact' -and $shotImpact -match 'TryApplyIndependentWeaponPointImpulse' -and $world -match 'ReferenceEquals\(body,\s*rig\.WeaponBody\)' -and $world -match 'TryWakeIndependentWeapon') "direct weapon hits wake and impulse the independent weapon without activating its parent corpse"
Assert-True ($nativeScene -match 'TwistStiffness' -and $nativeScene -match 'SwingStiffness' -and $nativeScene -match 'TwistContactDistance' -and $nativeBridge -match 'swing_y_limited' -and $nativeBridge -match 'PxD6Motion::eLOCKED') "external character joints preserve separate limit parameters and lock zero-width angular axes"
Assert-True ($nativeScene -match 'Projection\s*=\s*source\.enableProjection\s*\?\s*1u\s*:\s*0u' -and $nativeScene -match 'ProjectionLinearTolerance\s*=\s*source\.projectionDistance' -and $nativeScene -match 'ProjectionAngularTolerance\s*=\s*source\.projectionAngle\s*\*\s*Mathf\.Deg2Rad' -and $nativeScene -notmatch 'source\.enableProjection\s*\?\s*Mathf\.Max') "external character joints preserve Unity projection enablement and tolerances without synthetic fallbacks"
Assert-True ($world -match 'TryWakeIndependentWeapon' -and $world -match 'independentWeaponLifecycle=' -and $world -match '!HasDynamicIndependentWeapon\(rig\)[\s\S]{0,80}ReleaseEnvironment\(rig\)' -and $weaponState -notmatch 'ReleaseEnvironment\(rig\)' -and $grenade -match 'ShadowRagdollWorld\.IsSettled') "settled dynamic weapons retain their support corridor through sleep and wake independently from forces, explosions, and moving geometry"
Assert-True ($runtime -match 'ManualResetEventSlim' -and $runtime -notmatch 'TaskCompletionSource' -and $runtime -match '_stepWorkItem' -and $runtime -match 'an external simulation step is already in flight' -and $world -match 'ExternalStepWatchdogMilliseconds\s*=\s*500' -and $world -match 'MainWaitMilliseconds' -and $world -match 'ExternalMainWaitP99') "one-step signaling reuses one pooled step item, catastrophic watchdog, readiness, and p99 main-wait diagnostics are wired"
Assert-True ($runtime -match 'else if \(_asyncQueue\.Count != 0\) work = _asyncQueue\.Dequeue\(\)' -and $runtime -match 'private void EnqueueAsync\(OwnerWork work\)' -and $runtime -match 'private void MoveAsyncToFifo\(OwnerWork work\)' -and $runtime -match 'work\.Generation != _raidGeneration' -and $runtime -match 'AsyncChunkActors\s*=\s*4' -and $runtime -match 'AsyncChunkWork\s*=\s*12000' -and $runtime -match 'EstimateCreationWork' -and $runtime -match 'MaximumOutstandingChunks' -and $runtime -match 'class ChunkWork' -and $runtime -match 'class CommandWork' -and $runtime -match 'WorkPool<T>') "asynchronous environment work is a low-priority owner queue drained only while the FIFO is empty, bounded to small chunks by actor count and estimated geometry work, tagged with the raid generation, movable to the FIFO by a caller that blocks on it, and commands and steps use pooled typed items"
Assert-True ($runtime -match 'private OwnerWork _asyncActive' -and $runtime -match 'else if \(_asyncActive != null\)' -and $runtime -match 'private bool ExecuteSlice\(OwnerWork work\)' -and $runtime -match 'if \(!work\.Asynchronous\) continue;' -and $runtime -match 'internal virtual bool RunSlice\(ExternalPhysXRuntime runtime\)' -and $runtime -match 'abstract class SlicedCreationWork : OwnerWork' -and $runtime -match 'class ChunkWork : SlicedCreationWork' -and $runtime -match 'class PromotionWork : SlicedCreationWork' -and $runtime -match 'ReferenceEquals\(_asyncActive, work\)' -and $runtime -match 'work\.Asynchronous = true' -and $nativeScene -match 'internal bool CreateSlice\(ActorCreationCursor cursor\)' -and $nativeScene -match 'private bool PreloadGeometry\(ShapeSnapshot shape\)' -and $nativeScene -match 'AttachShapesPerSlice\s*=\s*16' -and $nativeScene -match 'if \(PreloadGeometry\(shapes\[cursor\.PreloadIndex\+\+\]\)\) return false;' -and $nativeScene -match 'if \(_requireResident\) InlineGeometryLoads\+\+;') "asynchronous environment creation is sliced: one owner turn loads at most one mesh or heightfield or creates one actor shell with a bounded number of resident shapes, the owner serves its FIFO between turns, a caller that blocks on an item takes it to the FIFO where it runs through, and a geometry the preload missed is loaded inline and counted"
Assert-True ($runtime -match 'QueuedBehindAsync = _asyncSliceRunning' -and $runtime -match 'RecordStepWaitBehindAsync\(System\.Diagnostics\.Stopwatch\.GetTimestamp\(\) - QueuedTimestamp\)' -and $runtime -match 'ownerAsync=items:\{_asyncItems\}/maxMs:' -and $runtime -match 'stepWaits:\{_stepAsyncWaits\}/stepWaitMaxMs:' -and $runtime -match 'preloads:' -and $runtime -match 'inlineLoads:') "the status line reports asynchronous owner items, the longest one, the steps queued behind a running asynchronous item with their longest wait, and the preloaded and inline geometry loads"
Assert-True ($prefetchContracts -match 'interface IExternalEnvironmentPrefetchRuntime' -and $prefetchContracts -match 'interface IExternalCreationBatchRuntime' -and $prefetchContracts -match '0xC000_0000u' -and $prefetchContracts -match '0x8000_0000u' -and $prefetchContracts -match 'raw <c>ShadowRig\.ExternalGroup</c>' -and $runtime -match 'IExternalEnvironmentPrefetchRuntime' -and $runtime -match 'IExternalCreationBatchRuntime' -and $runtime -match 'public double PumpEnvironmentPrefetch' -and $runtime -match 'public void PromoteEnvironmentPrefetch' -and $runtime -match 'ClassifyRegion\(center, sweepEnd, AcquisitionClaimResolution' -and $runtime -match 'private void DriveJob' -and $runtime -match '_claims\.TryGetValue\(colliderId, out CaptureJob owner\)') "environment prefetch stages capture across frames, submits chunks without waiting, never duplicates a claimed collider, and EnsureEnvironment resolves claimed colliders instead of recapturing them"
Assert-True ($runtime -match 'BeginCreationBatch' -and $runtime -match 'class CreationBatchWork' -and $runtime -match 'Rollback\(scene\)' -and $runtime -match 'RequireNativeHandle' -and $runtime -match 'The creation batch was abandoned by a raid reset' -and $runtime -match 'BindActors\(_child\.NativeHandle' -and $runtime -match 'void Bind\(ulong handle' -and $runtime -match 'private void AbandonCreationBatch' -and $runtime -match 'public void Abandon\(\)' -and $prefetchContracts -match 'interface IExternalCreationBatch\s*:\s*IDisposable') "a creation batch queues body and joint creation as one rolled-back owner transaction, can be abandoned without running, and wrappers refuse native-handle use until it is disposed"
Assert-True ($runtime -match 'ClearNoShapeCache\(\)' -and $runtime -match 'StartSceneCapture' -and $runtime -match 'StartDeferredCapture' -and $runtime -notmatch 'StartRuntimeCapture' -and $runtime -match 'class PromotionWork' -and $runtime -match 'MaximumPendingPromotions' -and $meshSources -match 'public void ClearNoShapeCache' -and $runtime -notmatch 'CaptureScene\(') "late scenes, deferred Unity shapes and static-to-kinematic replacement are staged through the asynchronous pipeline without a whole-scene remap, while runtime-spawned colliders are captured by the acquisition itself"
Assert-True ($runtime -match 'private void TakeOverClaims' -and $runtime -match 'CommitTakenSnapshots' -and $runtime -match 'ClaimResolution\.TakeOver' -and $runtime -match 'ClaimResolution\.Drive' -and $runtime -match 'SnapshotColliderIds' -and $runtime -match 'OwnsClaim\(job, collider\.GetInstanceID\(\)\)' -and $runtime -match 'private ClaimResolution AcquisitionClaimResolution\s*=>\s*_stageCasingEnvironment\s*\?\s*ClaimResolution\.Drive\s*:\s*ClaimResolution\.TakeOver' -and $runtime -match 'int reused = ClassifyRegion\(center, sweepEnd, AcquisitionClaimResolution, skipBodyShapes: true\);' -and $runtime -match 'job\.Kind == CaptureKind\.Prefetch && !IsFullPrebake\) ParkUnreferenced' -and $runtime -match 'private void AwaitChunk' -and $runtime -match 'private void RetireJob' -and $runtime -match 'MaximumPooledJobs') "a corpse or rig acquisition (both environment modes) takes over only its corridor's claimed colliders, never drives a whole late-scene job, keeps casings driving their jobs, parks only prefetch actors, and pools prefetch jobs"
